-- SOLO CI: usuarios, correos, depósitos y dinero ficticios; se revierte todo.
begin;
create function pg_temp.ok(v boolean,msg text) returns void language plpgsql as $$begin if v is not true then raise exception 'FAIL %',msg;end if;raise notice 'PASS %',msg;end;$$;
insert into auth.users(id,email) select ('10000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'fixture-'||i||'@example.invalid' from generate_series(1,4)i;
insert into public.cc_admins values('10000000-0000-4000-8000-000000000001');
insert into public.cc_user_details values('10000000-0000-4000-8000-000000000002','Comprador Ficticio Dos'),('10000000-0000-4000-8000-000000000003','Comprador Ficticio Tres');
insert into public.cc_clan_codes(user_id,code,code_number) select id,'CLAN'||row_number() over(order by id),row_number()over(order by id) from auth.users;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claim.role','authenticated',true);
select public.cc_recharge_create('20000000-0000-4000-8000-000000000001',20,'MANUAL_BANK');
select public.cc_recharge_create('20000000-0000-4000-8000-000000000001',20,'MANUAL_BANK');
select pg_temp.ok((select count(*)=1 from cc_internal.recharge_registry),'Reintento crea un solo REC');
select pg_temp.ok((select coalesce(sum(balance_pen),0)=0 from public.cc_real_service_wallets),'Crear REC no acredita ni genera bono');
select pg_temp.ok((public.cc_recharge_my_requests()->'requests'->0->>'rec_code') like 'REC-%','El usuario recibe su REC real');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select public.cc_recharge_create('20000000-0000-4000-8000-000000000002',20,'MANUAL_BANK');
select pg_temp.ok((select count(distinct rec_code)=2 from cc_internal.recharge_registry),'Dos usuarios con mismo importe tienen REC distintos');
select pg_temp.ok(jsonb_array_length(public.cc_recharge_my_requests()->'requests')=1,'Aislamiento por titular');
do $$begin begin perform public.cc_recharge_admin('overview');raise exception 'FAIL nonadmin';exception when insufficient_privilege then null;end;end;$$;
select pg_temp.ok(not has_function_privilege('anon','public.cc_recharge_create(uuid,numeric,text)','execute'),'Anon no crea REC');
select pg_temp.ok(not has_function_privilege('authenticated','public.cc_recharge_mail_service(text,jsonb)','execute'),'Cliente no puede insertar avisos de correo ni leer tokens');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
do $$declare rec text;begin select rec_code into rec from cc_internal.recharge_registry where user_id='10000000-0000-4000-8000-000000000002';
 begin perform public.cc_recharge_admin('approve',jsonb_build_object('rec_code',rec,'transaction_reference','BANK-TX-123456','source_bank','Banco ficticio','reason','Captura no suficiente','confirmed_received',false));raise exception 'FAIL screenshot';exception when others then if sqlerrm='FAIL screenshot' then raise;end if;end;
 perform pg_temp.ok((select coalesce(sum(balance_pen),0)=0 from public.cc_real_service_wallets),'Comprobante sin ingreso comprobado no acredita');
 perform public.cc_recharge_admin('clarify',jsonb_build_object('rec_code',rec,'reason','Confirma el titular del depósito'));
 perform pg_temp.ok((select status='CLARIFICATION' from cc_internal.recharge_registry where rec_code=rec),'Solicitud de aclaración sin crédito');
 perform public.cc_recharge_admin('approve',jsonb_build_object('rec_code',rec,'transaction_reference','BANK-TX-123456','source_bank','Banco ficticio','reason','Ingreso cotejado en cuenta receptora','confirmed_received',true));
 perform public.cc_recharge_admin('approve',jsonb_build_object('rec_code',rec,'transaction_reference','BANK-TX-123456','source_bank','Banco ficticio','reason','Ingreso cotejado en cuenta receptora','confirmed_received',true));
 perform pg_temp.ok((select sum(balance_pen)=20 from public.cc_real_service_wallets where user_id='10000000-0000-4000-8000-000000000002'),'Aprobación acredita exclusivamente al titular una sola vez');
 perform pg_temp.ok((select count(*)=1 from public.cc_real_wallet_ledger),'Una acreditación, un asiento');
 perform pg_temp.ok((select count(*)=1 from cc_internal.recharge_notifications where event='CREDITED'),'Notificación en panel solo tras asiento financiero');
end;$$;
-- Variante de escritura de la misma operación no puede financiar otra billetera.
do $$declare rec text;begin select rec_code into rec from cc_internal.recharge_registry where user_id='10000000-0000-4000-8000-000000000003';
 begin perform public.cc_recharge_admin('approve',jsonb_build_object('rec_code',rec,'transaction_reference','banktx123456','source_bank','Banco ficticio','reason','Intento duplicado con formato distinto','confirmed_received',true));raise exception 'FAIL reused transaction';exception when unique_violation then null;end;
 perform pg_temp.ok((select coalesce(sum(balance_pen),0)=0 from public.cc_real_service_wallets where user_id='10000000-0000-4000-8000-000000000003'),'La operación no acredita una segunda billetera');
 perform public.cc_recharge_admin('reject',jsonb_build_object('rec_code',rec,'reason','No corresponde a una operación nueva'));
 perform pg_temp.ok((select status='REJECTED' from cc_internal.recharge_registry where rec_code=rec),'Rechazo no acredita');
end;$$;
-- OAuth ADMIN, PKCE y mensajes idempotentes; los avisos nunca reservan dinero.
select set_config('request.jwt.claim.role','service_role',true);
select public.cc_recharge_mail_service('oauth_start',jsonb_build_object('actor_id','10000000-0000-4000-8000-000000000001','provider','google','state_hash',repeat('a',64),'verifier','FAKE-PKCE-VERIFIER'));
select pg_temp.ok(public.cc_recharge_mail_service('oauth_claim',jsonb_build_object('provider','google','state_hash',repeat('a',64)))->>'verifier'='FAKE-PKCE-VERIFIER','OAuth estado válido se consume');
do $$begin begin perform public.cc_recharge_mail_service('oauth_claim',jsonb_build_object('provider','google','state_hash',repeat('a',64)));raise exception 'FAIL reused state';exception when others then if sqlerrm='FAIL reused state' then raise;end if;end;end;$$;
select public.cc_recharge_mail_service('oauth_save','{"actor_id":"10000000-0000-4000-8000-000000000001","provider":"google","subject":"fake-owner","email":"deposits@fixture.invalid","tokens":{"access_token":"FAKE-TOKEN","refresh_token":"FAKE-REFRESH"}}');
do $$declare mailid uuid;beforebalance numeric;begin select c.id into mailid from cc_internal.recharge_mail_connections c limit 1;select sum(balance_pen) into beforebalance from public.cc_real_service_wallets;
 perform public.cc_recharge_mail_service('mail_notice',jsonb_build_object('actor_id','10000000-0000-4000-8000-000000000001','connection_id',mailid,'message_id','email-one','sender','bank@fixture.invalid','subject','Depósito recibido','sender_authenticated',true,'amount_hint',20,'currency_hint','PEN','transaction_hint','UNVERIFIED-REFERENCE','received_at',now()));
 perform public.cc_recharge_mail_service('mail_notice',jsonb_build_object('actor_id','10000000-0000-4000-8000-000000000001','connection_id',mailid,'message_id','email-one','sender','bank@fixture.invalid','subject','Depósito recibido','sender_authenticated',true,'amount_hint',20,'currency_hint','PEN','received_at',now()));
 perform public.cc_recharge_mail_service('mail_notice',jsonb_build_object('actor_id','10000000-0000-4000-8000-000000000001','connection_id',mailid,'message_id','email-two','sender','bank@fixture.invalid','subject','Depósito recibido','sender_authenticated',false,'amount_hint',20,'currency_hint','PEN','received_at',now()));
 perform pg_temp.ok((select count(*)=2 from cc_internal.recharge_mail_events),'Correo duplicado se registra una vez');
 perform pg_temp.ok((select sum(balance_pen)=beforebalance from public.cc_real_service_wallets),'Correos reales o falsos no modifican billeteras');
 perform pg_temp.ok((select count(*)=2 from cc_internal.recharge_mail_events where linked_rec_id is null and status='UNIDENTIFIED'),'Importes iguales nunca identifican usuarios');
 perform public.cc_recharge_mail_service('mail_disconnect',jsonb_build_object('actor_id','10000000-0000-4000-8000-000000000001','connection_id',mailid));
 perform pg_temp.ok((select token_secret_id is null from cc_internal.recharge_mail_connections c where c.id=mailid),'Desconexión elimina vínculo al token');
end;$$;
-- La ruta oficial Merchant confirma importe y orden, no un correo ni un importe parecido.
select public.cc_binance_merchant_reserve('10000000-0000-4000-8000-000000000003','STREAM_BULLS',10,repeat('b',32));
update public.cc_binance_merchant_orders set status='READY',expected_usdt=2.5,merchant_id='MERCHANT-FAKE',prepay_id='PREPAY-FAKE';
do $$begin begin perform public.cc_binance_merchant_credit(repeat('b',32),'MERCHANT-FAKE','PREPAY-FAKE','MERCHANT-TX-123456',2.4,now());raise exception 'FAIL amount mismatch';exception when others then if sqlerrm='FAIL amount mismatch' then raise;end if;end;end;$$;
select public.cc_binance_merchant_credit(repeat('b',32),'MERCHANT-FAKE','PREPAY-FAKE','MERCHANT-TX-123456',2.5,now());
select public.cc_binance_merchant_credit(repeat('b',32),'MERCHANT-FAKE','PREPAY-FAKE','MERCHANT-TX-123456',2.5,now());
select pg_temp.ok((select sum(balance_pen)=10 from public.cc_real_service_wallets where user_id='10000000-0000-4000-8000-000000000003'),'Confirmación oficial vinculada acredita exactamente una vez');
select pg_temp.ok((select status='CREDITED' and credit_id is not null and payment_amount=2.5 from cc_internal.recharge_registry where origin='MERCHANT'),'REC automático apunta a su asiento y activo recibido');
-- Reversión del depósito, y deuda si el saldo ya se gastó.
select set_config('request.jwt.claim.role','authenticated',true);
do $$declare rec text;begin select rec_code into rec from cc_internal.recharge_registry where user_id='10000000-0000-4000-8000-000000000002';
 update public.cc_real_service_wallets set balance_pen=5 where user_id='10000000-0000-4000-8000-000000000002';
 perform public.cc_recharge_admin('reverse',jsonb_build_object('rec_code',rec,'request_id','30000000-0000-4000-8000-000000000001','bank_reference','REVERSAL-BANK-1234','reason','Anulación bancaria ficticia comprobada','confirmed_reversed',true));
 perform public.cc_recharge_admin('reverse',jsonb_build_object('rec_code',rec,'request_id','30000000-0000-4000-8000-000000000001','bank_reference','REVERSAL-BANK-1234','reason','Anulación bancaria ficticia comprobada','confirmed_reversed',true));
 perform pg_temp.ok((select recovered_pen=5 from cc_internal.recharge_reversals),'Reversión recupera saldo existente una sola vez');
 perform pg_temp.ok((select status='REVERSAL_PENDING' from cc_internal.recharge_registry where rec_code=rec),'Saldo gastado genera reversión pendiente sin balance negativo');end;$$;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select pg_temp.ok((public.cc_finance_wallet()->>'pending_reversal_pen')::numeric=15,'La billetera común incluye deuda pendiente de recarga anulada');
select pg_temp.ok(jsonb_array_length(public.cc_recharge_my_movements())=1,'Reversión visible en movimientos de la misma billetera');
-- Precios nuevos y periodos anteriores: tres mensuales de 15 y STREAM anual de 25.
insert into public.cc_businesses(code) values('COBRA_YA'),('MI_COCHERA'),('MI_ALQUILER'),('STREAM_BULLS');
insert into public.cc_plans(business_id,code,title,billing_type,price_pen,is_active) select id,'STREAM_365','Anual','ONE_TIME',25,true from public.cc_businesses where code='STREAM_BULLS';
insert into public.cc_real_service_wallets(user_id,service,balance_pen) values('10000000-0000-4000-8000-000000000004','STREAM_BULLS',100);
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',true);
select public.cc_finance_pay_membership('COBRA_YA','40000000-0000-4000-8000-000000000001',15);
select public.cc_finance_pay_membership('MI_COCHERA','40000000-0000-4000-8000-000000000002',15);
select public.cc_finance_pay_membership('MI_ALQUILER','40000000-0000-4000-8000-000000000003',15);
do $$declare r jsonb;begin r:=public.cc_finance_pay_membership('STREAM_BULLS','40000000-0000-4000-8000-000000000004',25);perform pg_temp.ok((r->>'active_until')::timestamptz=((now() at time zone 'America/Lima')+interval '1 year') at time zone 'America/Lima','STREAM concede año, no mes');end;$$;
select pg_temp.ok((select sum(balance_pen)=30 from public.cc_real_service_wallets where user_id=auth.uid()),'Tarifas 15+15+15+25 sin duplicar saldo');
select pg_temp.ok((select count(*)=0 from cc_internal.finance_referral_bonuses),'Recargas sin activación referida no generan bonos');
rollback;
